function NavigationScreen({data,destination,path,guide,lang,distanceVerified,onPick,onExit}:{data:Campus;destination:Node;path?:string[];guide:ReturnType<typeof useLiveGuide>;lang:'en'|'ta';distanceVerified:boolean;onPick:(id:string)=>void;onExit:()=>void}){
 useEffect(()=>{const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=old}},[]);
 const status=(guide.error?t(lang,guide.error):'')||(!guide.fix?t(lang,'Finding your position…'):guide.fix.accuracy>35?`GPS ${t(lang,'accuracy')} ±${Math.round(guide.fix.accuracy)} m. ${t(lang,'Move outdoors for a clearer fix.')}`:guide.instruction?.text||t(lang,'Checking your position against the mapped paths…'));
 const routeDistance=guide.path?.meters;
 return <div className="navigation-screen" role="dialog" aria-modal="true" aria-label={t(lang,'Navigation to ')+place(lang,destination.name)}>
  <div className="navigation-top"><button className="navigation-exit" onClick={onExit} aria-label={t(lang,'Close navigation')}><ArrowLeft size={21}/></button><div><span>{t(lang,"GUIDING TO")}</span><strong>{place(lang,destination.name)}</strong></div><span className="navigation-live"><span/>{t(lang,"LIVE")}</span></div>
  <div className="navigation-map"><CampusMap lang={lang} data={data} path={path} destination={destination.id} onPick={onPick} fix={guide.fix} live={guide.active}/></div>
  <div className="navigation-bottom"><div className="navigation-prompt"><span className="navigation-prompt-icon"><Navigation size={25}/></span><div><strong role="status">{status}</strong><small>{guide.fix?`GPS ±${Math.round(guide.fix.accuracy)} m · ${t(lang,data.gpsCalibrated?'Outdoor position':'Approximate map alignment')}`:t(lang,'Allow location access for live guidance')}</small></div></div><div className="navigation-meta"><span>{distanceVerified&&routeDistance?`${t(lang,'About')} ${routeDistance} m · ${guide.path?.minutes} ${t(lang,'min walk')}`:t(lang,'Follow the marked campus path')}</span><label>{t(lang,'Voice')} <Switch checked={guide.voice} onCheckedChange={guide.setVoice}/></label><button onClick={()=>guide.start(true)} disabled={guide.active&&!guide.error}>{t(lang,guide.error?'Retry GPS':'GPS on')}</button></div><div className="navigation-caution">{t(lang,"Outdoor GPS can drift. Inside buildings, scan a posted checkpoint to set your position.")}</div><button className="navigation-stop" onClick={onExit}>{t(lang,"End navigation")}</button></div>
 </div>
}
function Admin({data,setData,staff,back,logout,lang}:{lang:Lang;data:Campus;setData:(c:Campus)=>void;staff:{authorized:boolean;owner:boolean;signedIn:boolean;configured:boolean;email:string|null};back:()=>void;logout:()=>void}){
 const [draft,setDraft]=useState<Campus>(()=>structuredClone(data)),[tab,setTab]=useState<'overview'|'events'|'directory'|'map'|'facilities'|'alerts'|'visitors'|'data'>('overview'),[message,setMessage]=useState('');const upload=useRef<HTMLInputElement>(null);
 function edit(fn:(d:Campus)=>void){setDraft(old=>{const next=structuredClone(old);fn(next);return next})}
 async function publish(){try{const res=await fetch('/api/campus',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(draft)});const body=await res.json() as Campus & {error?:string};if(!res.ok)throw Error(body.error);setDraft(body);setData(body);localStorage.setItem('kpr-compass-campus',JSON.stringify(body));setMessage('Published campus data version '+body.version)}catch(e:any){setMessage(e.message||'Publish failed')}}
 async function importFile(file?:File){if(!file)return;try{const obj=JSON.parse(await file.text());if(!obj.nodes||!obj.edges||!obj.events||!obj.facilities||!obj.alerts)throw Error('The file must contain nodes, edges, events, facilities, and alerts.');setDraft(obj);setMessage('Imported draft. Review it before publishing.')}catch(e:any){setMessage(e.message)}}
 function exportJSON(){const b=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'});const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download='kpr-compass-map.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
 return <div className="admin"><div className="page-top"><div><span className="eyebrow">{t(lang,"STAFF WORKSPACE")}</span><h1>{t(lang,"Campus operations")}</h1><p>{t(lang,"Manage the information visitors see and the paths they can use.")}</p></div><div className="admin-header-actions"><button className="back-link" onClick={back}><ArrowLeft size={17}/>{t(lang,"Visitor view")}</button><button className="back-link" onClick={logout}>{t(lang,"Lock admin")}</button></div></div><div className="admin-banner"><Settings2 size={20}/><div><strong>{t(lang,staff.authorized?'Authorized staff session':staff.signedIn?'Staff access needed':'Staff sign-in required')}</strong><span>{staff.authorized?`${t(lang,'Signed in as ')}${staff.email}. ${t(lang,'Changes are published to all visitors.')}`:t(lang,staff.configured?'This account is not on the staff allowlist. You can inspect the dashboard, but publishing is disabled.':'Set the ADMIN_EMAIL runtime setting to an authorized staff email before enabling publishing. The dashboard is read-only until then.')}</span></div>{!staff.signedIn&&<a href="/signin-with-chatgpt?return_to=%2Fadmin" target="_top">{t(lang,"Sign in")}</a>}</div><div className="admin-layout"><div className="admin-tabs"><button className={tab==='overview'?'active':''} onClick={()=>setTab('overview')}>{t(lang,"Overview")}</button><button className={tab==='events'?'active':''} onClick={()=>setTab('events')}>{t(lang,"Events")}</button><button className={tab==='directory'?'active':''} onClick={()=>setTab('directory')}>{t(lang,"Departments & cabins")}</button><button className={tab==='map'?'active':''} onClick={()=>setTab('map')}>{t(lang,"Map & paths")}</button><button className={tab==='facilities'?'active':''} onClick={()=>setTab('facilities')}>{t(lang,"Facilities")}</button><button className={tab==='alerts'?'active':''} onClick={()=>setTab('alerts')}>{t(lang,"Alerts")}</button><button className={tab==='visitors'?'active':''} onClick={()=>setTab('visitors')}>{t(lang,"Visitor check-in")}</button><button className={tab==='data'?'active':''} onClick={()=>setTab('data')}>{t(lang,"Import & QR")}</button></div><div className="admin-work"><div className="admin-work-head"><div><span className="section-kicker">DRAFT · VERSION {draft.version}</span><h2>{t(lang,({overview:'Overview',events:'Events & venues',directory:'Departments & cabins',map:'Map & closures',facilities:'Facilities',alerts:'Venue alerts',visitors:'Visitor check-in',data:'Campus data & checkpoints'} as const)[tab])}</h2></div><Button onClick={publish} disabled={!staff.authorized}>{t(lang,"Publish changes")}</Button></div>{message&&<div className="admin-message" role="status">{t(lang,message)}</div>}
 {tab==='overview'&&<div className="admin-overview"><div className="admin-metrics"><article><span>{t(lang,"Campus places")}</span><strong>{draft.nodes.filter(n=>n.kind!=='junction').length}</strong></article><article><span>{t(lang,"Published events")}</span><strong>{draft.events.length}</strong></article><article><span>{t(lang,"Verified rooms")}</span><strong>{(draft.rooms||[]).filter(r=>r.verified).length}</strong></article><article><span>{t(lang,"Closed paths")}</span><strong>{draft.edges.filter(e=>e.closed).length}</strong></article></div><div className="editor-card"><h3>{t(lang,"Ready for visitors")}</h3><p>{t(lang,"Review venue details, map paths and room directions before publishing. Changes stay in this draft until you select Publish changes.")}</p><div className="overview-actions"><Button variant="outline" onClick={()=>setTab('events')}>{t(lang,"Manage events")}</Button><Button variant="outline" onClick={()=>setTab('directory')}>{t(lang,"Add a cabin")}</Button><Button variant="outline" onClick={()=>setTab('map')}>{t(lang,"Review paths")}</Button></div></div>{!draft.gpsCalibrated&&<div className="admin-callout">{t(lang,"Outdoor GPS is approximate. Capture three on-campus anchors in Map & paths to calibrate it.")}</div>}{!draft.accessibilityVerified&&<div className="admin-callout">{t(lang,"Step-free routes need surveyed ramps, lifts and path details.")}</div>}</div>}
 {tab==='events'&&<><p className="help-text">{t(lang,"Publish verified event details and venue. Enable participation when registration is ready. Visitors see changes after publishing.")}</p>{draft.events.map((e,i)=><div className="editor-card" key={e.id}><div className="editor-card-title"><strong>{e.title||`Event ${i+1}`}</strong><button onClick={()=>edit(d=>{d.events=d.events.filter(x=>x.id!==e.id)})}>{t(lang,"Delete event")}</button></div><label>{t(lang,"Name")}<input value={e.title} onChange={x=>edit(d=>{d.events[i].title=x.target.value})}/></label><div className="two-col"><label>{t(lang,"Time shown to visitors")}<input value={e.time} onChange={x=>edit(d=>{d.events[i].time=x.target.value})}/></label><label>{t(lang,"Venue")}<select value={e.venue} onChange={x=>edit(d=>{d.events[i].venue=x.target.value})}>{draft.nodes.filter(n=>n.kind!=='junction').map(n=><option key={n.id} value={n.id}>{place(lang,n.name)}</option>)}{(draft.rooms||[]).filter(r=>r.verified).map(r=><option key={r.id} value={r.id}>{r.name} · {draft.nodes.find(n=>n.id===r.building)?.name}</option>)}</select></label></div><div className="two-col"><label>{t(lang,"Starts at")}<input type="datetime-local" value={dateLocal(e.startsAt)} onChange={x=>edit(d=>{d.events[i].startsAt=x.target.value?new Date(x.target.value).toISOString():undefined})}/></label><label>{t(lang,"Ends at")}<input type="datetime-local" value={dateLocal(e.endsAt)} onChange={x=>edit(d=>{d.events[i].endsAt=x.target.value?new Date(x.target.value).toISOString():undefined})}/></label></div><small>{t(lang,"Enter local campus time to show Upcoming, Happening now and Past.")}</small><label>{t(lang,"Description")}<textarea value={e.description||''} maxLength={1000} onChange={x=>edit(d=>{d.events[i].description=x.target.value})}/></label><label>{t(lang,"Tamil title")}<input value={e.titleTa||''} onChange={x=>edit(d=>{d.events[i].titleTa=x.target.value})}/></label><label>{t(lang,"Tamil time")}<input value={e.timeTa||''} onChange={x=>edit(d=>{d.events[i].timeTa=x.target.value})}/></label><label>{t(lang,"Tamil description")}<textarea value={e.descriptionTa||''} maxLength={1000} onChange={x=>edit(d=>{d.events[i].descriptionTa=x.target.value})}/></label><label>{t(lang,"Entry instructions")}<textarea value={e.instructions} onChange={x=>edit(d=>{d.events[i].instructions=x.target.value})}/></label><label>{t(lang,"Tamil entry instructions")}<textarea value={e.instructionsTa||''} onChange={x=>edit(d=>{d.events[i].instructionsTa=x.target.value})}/></label><div className="poster-editor"><strong>{t(lang,"Event poster")}</strong>{e.posterUrl&&<img src={e.posterUrl} alt={e.title+' poster preview'}/>}<div><label className="poster-upload">{t(lang,"Upload poster (up to 10 MB)")}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={async x=>{const file=x.target.files?.[0];if(!file)return;if(file.size>10_000_000){setMessage('Poster must be under 10 MB.');return}const form=new FormData();form.append('file',file);try{const res=await fetch('/api/event-poster',{method:'POST',body:form});const body=await res.json() as {url?:string;error?:string};if(!res.ok||!body.url)throw Error(body.error||'Poster upload failed');edit(d=>{d.events[i].posterUrl=body.url});setMessage('Poster uploaded. Publish changes to show visitors.')}catch(err){setMessage(err instanceof Error?err.message:'Poster upload failed')}}}/></label>{e.posterUrl&&<button onClick={()=>edit(d=>{d.events[i].posterUrl=undefined})}>{t(lang,"Remove poster")}</button>}</div></div><label className="check-row"><input type="checkbox" checked={!!e.registrationOpen} onChange={x=>edit(d=>{d.events[i].registrationOpen=x.target.checked})}/>{t(lang,"Accept visitor registrations")}</label></div>)}<Button variant="outline" onClick={()=>edit(d=>d.events.push({id:crypto.randomUUID(),title:'',venue:d.nodes[0]?.id||'',time:'',instructions:'',registrationOpen:false}))}><Plus size={17}/>{t(lang,"Add event")}</Button><EventRoster lang={lang} authorized={staff.authorized}/></>}
 {tab==='directory'&&<div className="directory-editor"><p className="help-text">{t(lang,"Add only rooms you have checked in person. A room appears in visitor search after you mark it verified. Link a surveyed checkpoint for indoor guidance; otherwise navigation ends at the building.")}</p>{(draft.rooms||[]).map((r,i)=><div className="editor-card" key={r.id}><div className="editor-card-title"><strong>{r.name||'New room'}</strong><button onClick={()=>{if(draft.events.some(e=>e.venue===r.id)){setMessage('Move events from this venue before removing it.');return}edit(d=>{d.rooms=d.rooms?.filter(x=>x.id!==r.id)})}}>{t(lang,"Remove")}</button></div><div className="directory-fields"><label>{t(lang,"Cabin / room name")}<input value={r.name} onChange={e=>edit(d=>{d.rooms![i].name=e.target.value})}/></label><label>{t(lang,"Department")}<input value={r.department} onChange={e=>edit(d=>{d.rooms![i].department=e.target.value})}/></label><label>{t(lang,"Building")}<select value={r.building} onChange={e=>edit(d=>{d.rooms![i].building=e.target.value})}>{draft.nodes.filter(n=>n.floor===0&&n.kind!=='junction').map(n=><option key={n.id} value={n.id}>{place(lang,n.name)}</option>)}</select></label><label>{t(lang,"Floor (optional)")}<input type="number" placeholder={t(lang,'Unknown')} value={r.floor??''} onChange={e=>edit(d=>{d.rooms![i].floor=e.target.value===''?null:Number(e.target.value)})}/></label><label>{t(lang,"Room number")}<input value={r.roomNumber} onChange={e=>edit(d=>{d.rooms![i].roomNumber=e.target.value})}/></label><label>{t(lang,"QR checkpoint")}<select value={r.checkpoint||''} onChange={e=>edit(d=>{d.rooms![i].checkpoint=e.target.value||undefined})}><option value="">{t(lang,"None — building entrance only")}</option>{draft.nodes.map(n=><option key={n.id} value={n.id}>{place(lang,n.name)}</option>)}</select></label></div><label>{t(lang,"Indoor directions")}<textarea value={r.directions} onChange={e=>edit(d=>{d.rooms![i].directions=e.target.value})}/></label><label className="check-row"><input type="checkbox" checked={r.verified} onChange={e=>edit(d=>{d.rooms![i].verified=e.target.checked})}/>{t(lang,"Verified on site and visible to visitors")}</label></div>)}<Button variant="outline" onClick={()=>edit(d=>{d.rooms=[...(d.rooms||[]),{id:crypto.randomUUID(),name:'',department:'',building:d.nodes.find(n=>n.kind==='building')?.id||d.nodes[0].id,floor:0,roomNumber:'',directions:'',verified:false}]})}><Plus size={17}/>{t(lang,"Add room")}</Button></div>}
 {tab==='map'&&<><p className="help-text">{t(lang,"Nodes locate entrances, floors, and rooms. Connected paths power walking directions. Closing an edge immediately removes it from route calculations after publication.")}</p><div className="editor-card"><div className="editor-card-title"><strong>{t(lang,"Map status")}</strong><span>{draft.nodes.length} points · {draft.edges.length} paths</span></div><label>{t(lang,"Map name")}<input value={draft.mapName} onChange={x=>edit(d=>{d.mapName=x.target.value})}/></label><label className="check-row"><input type="checkbox" checked={draft.verified} onChange={x=>edit(d=>{d.verified=x.target.checked})}/>{t(lang,"Destination labels checked against the published campus layout")}</label><label className="check-row"><input type="checkbox" checked={!!draft.distanceVerified} onChange={x=>edit(d=>{d.distanceVerified=x.target.checked})}/>{t(lang,"Path lengths measured on site")}</label><label className="check-row"><input type="checkbox" checked={!!draft.accessibilityVerified} onChange={x=>edit(d=>{d.accessibilityVerified=x.target.checked})}/>{t(lang,"Ramps, lifts and step-free edges surveyed on site")}</label><small>{t(lang,"Only enable measured distances or step-free routing after a physical survey.")}</small></div><h3>{t(lang,"Paths and closures")}</h3>{draft.edges.map((e,i)=><div className="edge-row" key={e.id}><div><strong>{draft.nodes.find(n=>n.id===e.from)?.name} → {draft.nodes.find(n=>n.id===e.to)?.name}</strong><small>{e.stairs?'Stair route':'Step-free path'}</small></div><label className="edge-meters">{t(lang,"metres")}<input type="number" min="1" value={e.meters} onChange={x=>edit(d=>{d.edges[i].meters=Number(x.target.value)})}/></label><label className="check-row"><input type="checkbox" checked={!!e.stairs} onChange={x=>edit(d=>{d.edges[i].stairs=x.target.checked})}/>{t(lang,"Stairs")}</label><label className="check-row"><input type="checkbox" checked={!!e.closed} onChange={x=>edit(d=>{d.edges[i].closed=x.target.checked})}/>{t(lang,"Closed")}</label><button onClick={()=>edit(d=>{d.edges=d.edges.filter(x=>x.id!==e.id)})}>{t(lang,"Remove")}</button></div>)}<div className="add-row"><select id="edge-from" defaultValue={draft.nodes[0]?.id}>{draft.nodes.map(n=><option key={n.id} value={n.id}>{place(lang,n.name)}</option>)}</select><select id="edge-to" defaultValue={draft.nodes[1]?.id}>{draft.nodes.map(n=><option key={n.id} value={n.id}>{place(lang,n.name)}</option>)}</select><Button variant="outline" onClick={()=>{const a=(document.querySelector('#edge-from') as unknown as {value:string}).value,b=(document.querySelector('#edge-to') as unknown as {value:string}).value;if(a!==b)edit(d=>d.edges.push({id:crypto.randomUUID(),from:a,to:b,meters:50}))}}>{t(lang,"Add path")}</Button></div><h3>{t(lang,"Floor map images")}</h3><p className="help-text">{t(lang,"Upload an approved PNG, JPEG, or WebP plan for each floor. Position map points using X/Y percentages over that image.")}</p>{[...new Set(draft.nodes.map(n=>n.floor))].sort((a,b)=>a-b).map(f=><div className="map-upload-row" key={f}><strong>{f===0?'Ground floor':'Floor '+f}</strong><span>{draft.mapImages?.[String(f)]?'Image uploaded':'Schematic only'}</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;const form=new FormData();form.append('file',file);form.append('floor',String(f));try{const res=await fetch('/api/map-image',{method:'POST',body:form});const body=await res.json() as {url?:string;error?:string};if(!res.ok||!body.url)throw Error(body.error||'Upload failed');edit(d=>{d.mapImages={...d.mapImages,[String(f)]:body.url!}});setMessage('Map image uploaded. Publish changes to show visitors.')}catch(err:any){setMessage(err.message)}}}/></div>)}<h3>{t(lang,"GPS calibration")}</h3><p className="help-text">{t(lang,"The initial alignment uses public map coordinates for three buildings. At each building, capture a GPS fix outdoors to improve live guidance.")}</p>{['admin','mechanical','kalaiarangam'].map(id=>{const anchor=draft.nodes.find(n=>n.id===id);if(!anchor)return null;return <div className="anchor-row" key={id}><strong>{anchor.name}</strong><label>{t(lang,"Latitude")}<input type="number" step="0.000001" value={anchor.lat??''} onChange={e=>edit(d=>{d.nodes.find(n=>n.id===id)!.lat=Number(e.target.value)})}/></label><label>{t(lang,"Longitude")}<input type="number" step="0.000001" value={anchor.lon??''} onChange={e=>edit(d=>{d.nodes.find(n=>n.id===id)!.lon=Number(e.target.value)})}/></label><button onClick={()=>navigator.geolocation?.getCurrentPosition(p=>{if(p.coords.accuracy>20){setMessage('GPS accuracy is too low. Move outdoors and try again.');return}edit(d=>{const n=d.nodes.find(n=>n.id===id)!;n.lat=p.coords.latitude;n.lon=p.coords.longitude});setMessage('Captured '+anchor.name+' at ±'+Math.round(p.coords.accuracy)+' m. Review before publishing.')},()=>setMessage('Location unavailable. Enable location access and try again.'),{enableHighAccuracy:true,timeout:15000})}>{t(lang,"Use my location")}</button></div>})}<label className="check-row gps-check"><input type="checkbox" checked={!!draft.gpsCalibrated} onChange={e=>edit(d=>{d.gpsCalibrated=e.target.checked})}/>{t(lang,"Three GPS anchors surveyed on campus")}</label><h3>{t(lang,"Map points")}</h3>{draft.nodes.map((n,i)=><div className="node-row" key={n.id}><input aria-label={t(lang,'Point name')} value={n.name} onChange={x=>edit(d=>{d.nodes[i].name=x.target.value})}/><input aria-label={t(lang,'Search aliases for ')+n.name} placeholder={t(lang,'Search aliases, comma separated')} value={(n.aliases||[]).join(', ')} onChange={x=>edit(d=>{d.nodes[i].aliases=x.target.value.split(',').map(v=>v.trim()).filter(Boolean)})}/><label>X <input type="number" min="0" max="100" value={n.x} onChange={x=>edit(d=>{d.nodes[i].x=Number(x.target.value)})}/></label><label>Y <input type="number" min="0" max="100" value={n.y} onChange={x=>edit(d=>{d.nodes[i].y=Number(x.target.value)})}/></label><label>Floor <input type="number" value={n.floor} onChange={x=>edit(d=>{d.nodes[i].floor=Number(x.target.value)})}/></label><button className="node-remove" onClick={()=>{if(draft.edges.some(e=>e.from===n.id||e.to===n.id)||draft.events.some(e=>e.venue===n.id)||(draft.rooms||[]).some(r=>r.building===n.id||r.checkpoint===n.id)||draft.facilities.some(f=>f.node===n.id)){setMessage('Remove linked paths, events, rooms and facilities before deleting this point.');return}edit(d=>{d.nodes=d.nodes.filter(x=>x.id!==n.id)})}}>{t(lang,"Remove")}</button></div>)}<Button variant="outline" onClick={()=>edit(d=>d.nodes.push({id:'point-'+crypto.randomUUID().slice(0,8),name:'New checkpoint',x:50,y:50,floor:0,kind:'landmark'}))}><Plus size={17}/>{t(lang,"Add map point")}</Button></>}
 {tab==='facilities'&&<><p className="help-text">{t(lang,"Link each facility to a verified map point so visitors can route to it.")}</p>{draft.facilities.map((f,i)=><div className="facility-editor" key={f.id}><input aria-label={t(lang,'Facility name')} value={f.name} onChange={x=>edit(d=>{d.facilities[i].name=x.target.value})}/><select value={f.node} onChange={x=>edit(d=>{d.facilities[i].node=x.target.value})}>{draft.nodes.map(n=><option key={n.id} value={n.id}>{place(lang,n.name)}</option>)}</select><button onClick={()=>edit(d=>{d.facilities=d.facilities.filter(x=>x.id!==f.id)})}>{t(lang,"Remove")}</button></div>)}<Button variant="outline" onClick={()=>edit(d=>d.facilities.push({id:crypto.randomUUID(),name:'New facility',kind:'help',node:d.nodes[0]?.id||''}))}><Plus size={17}/>{t(lang,"Add facility")}</Button></>}
 {tab==='alerts'&&<><p className="help-text">{t(lang,"Publish a concise alert when a venue changes. Edit the event venue too so its Navigate button points to the new location.")}</p>{draft.alerts.map((a,i)=><div className="editor-card" key={a.id}><label>{t(lang,"Message")}<input value={a.message} onChange={x=>edit(d=>{d.alerts[i].message=x.target.value})}/></label><label>{t(lang,"Related event")}<select value={a.eventId||''} onChange={x=>edit(d=>{d.alerts[i].eventId=x.target.value})}><option value="">{t(lang,"Campus-wide")}</option>{draft.events.map(e=><option key={e.id} value={e.id}>{e.title}</option>)}</select></label><button onClick={()=>edit(d=>{d.alerts=d.alerts.filter(x=>x.id!==a.id)})}>{t(lang,"Remove alert")}</button></div>)}<Button variant="outline" onClick={()=>edit(d=>d.alerts.push({id:crypto.randomUUID(),message:'Venue changed — check updated directions.'}))}><Plus size={17}/>{t(lang,"Add alert")}</Button></>}
 {tab==='visitors'&&<BadgeDesk lang={lang} events={draft.events}/>}
 {tab==='data'&&<><div className="editor-card"><h3>{t(lang,"Maintain the campus dataset")}</h3><p>{t(lang,"The initial destinations come from KPRIET's published campus layout. Survey current paths and floors before enabling precise estimates. Record each point as a node with a unique ID, name, X/Y map coordinates (0–100), floor, and kind. Connect points with edges containing measured metres and stairs status. Link events and facilities to node IDs. Import the JSON, inspect all routes and closures, then publish the updates.")}</p><div className="button-row"><Button variant="outline" onClick={exportJSON}><Download size={17}/>{t(lang,"Download template JSON")}</Button><Button variant="outline" onClick={()=>upload.current?.click()}><Upload size={17}/>{t(lang,"Import JSON")}</Button><input ref={upload} type="file" accept="application/json,.json" hidden onChange={e=>importFile(e.target.files?.[0])}/></div></div><div className="editor-card"><h3>{t(lang,"Checkpoint links")}</h3><p>{t(lang,"Place printed QR codes at surveyed points. Each QR should encode the link below. The printed node ID also works when a phone cannot scan.")}</p>{draft.nodes.map(n=><div className="checkpoint-row" key={n.id}><div><strong>{place(lang,n.name)}</strong><small>Code: {n.id} · floor {n.floor}</small></div><button onClick={async()=>{await navigator.clipboard.writeText(location.origin+'/?checkpoint='+encodeURIComponent(n.id));setMessage('Checkpoint link copied for '+n.name)}}><Copy size={15}/>{t(lang,"Copy link")}</button><button onClick={async()=>{const url=await QRCode.toDataURL(location.origin+'/?checkpoint='+encodeURIComponent(n.id),{width:640,margin:3});const a=document.createElement('a');a.href=url;a.download='kpr-compass-qr-'+n.id+'.png';a.click()}}><Download size={15}/>{t(lang,"Download QR")}</button></div>)}</div></>}
 </div></div></div>
}
function AdminGate({staff,back,unlocked,lang}:{lang:Lang;staff:{authorized:boolean;owner:boolean;signedIn:boolean;configured:boolean;email:string|null};back:()=>void;unlocked:()=>void}){const [username,setUsername]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const response=await fetch('/api/admin-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,password})});const body=await response.json() as {error?:string};if(!response.ok)throw Error(body.error||'Sign-in failed');setPassword('');unlocked()}catch(e:any){setError(e.message)}finally{setBusy(false)}}return <div className="admin-gate"><div className="admin-login-card"><span className="login-icon"><Settings2 size={24}/></span><h1>{t(lang,"Admin portal")}</h1><p>{t(lang,"Manage events, routes and campus places.")}</p>{!staff.owner&&<div className="owner-required"><p>{t(lang,staff.signedIn?'This account cannot publish campus directions.':'Sign in with the site owner account to manage this project.')}</p>{!staff.signedIn&&<a href="/signin-with-chatgpt?return_to=%2Fadmin" target="_top">{t(lang,"Owner sign-in")}</a>}</div>}<form onSubmit={submit}><label>{t(lang,"Username")}<input autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} required/></label><label>{t(lang,"Password")}<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<div className="login-error" role="alert">{t(lang,error)}</div>}<Button type="submit" disabled={busy||!staff.owner} className="wide">{t(lang,busy?'Signing in…':'Sign in')}</Button></form><button className="login-back" onClick={back}><ArrowLeft size={15}/>{t(lang,"Back to campus")}</button></div></div>}
